    linear-gradient(rgba(155,89,182,0.75), rgba(155,89,182,0.75)) bottom right  / 10px 1px no-repeat,
    linear-gradient(rgba(155,89,182,0.75), rgba(155,89,182,0.75)) bottom right  / 1px 10px no-repeat;
}
.trick-cost {
