  cursor: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='28' height='28' viewBox='0 0 28 28'><defs><filter id='g' x='-50%25' y='-50%25' width='200%25' height='200%25'><feGaussianBlur stdDeviation='1.2'/></filter></defs><g filter='url(%23g)' stroke='%23ff8a7a' stroke-width='2.2' fill='none' opacity='0.80'><path d='M6 6 L6 17 L10 14.5 L13 20 L15 19 L12 13.5 L17 13.5 Z'/></g><path d='M6 6 L6 17 L10 14.5 L13 20 L15 19 L12 13.5 L17 13.5 Z' fill='%23ffffff' stroke='%23000000' stroke-width='0.8' stroke-linejoin='round'/></svg>") 4 4, default;
}
body.theme-gold {
  cursor: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='28' height='28' viewBox='0 0 28 28'><defs><filter id='g' x='-50%25' y='-50%25' width='200%25' height='200%25'><feGaussianBlur stdDeviation='1.2'/></filter></defs><g filter='url(%23g)' stroke='%23ffe066' stroke-width='2.2' fill='none' opacity='0.80'><path d='M6 6 L6 17 L10 14.5 L13 20 L15 19 L12 13.5 L17 13.5 Z'/></g><path d='M6 6 L6 17 L10 14.5 L13 20 L15 19 L12 13.5 L17 13.5 Z' fill='%23ffffff' stroke='%23000000' stroke-width='0.8' stroke-linejoin='round'/></svg>") 4 4, default;
}
body.theme-green {
  cursor: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='28' height='28' viewBox='0 0 28 28'><defs><filter id='g' x='-50%25' y='-50%25' width='200%25' height='200%25'><feGaussianBlur stdDeviation='1.2'/></filter></defs><g filter='url(%23g)' stroke='%237ee8a5' stroke-width='2.2' fill='none' opacity='0.80'><path d='M6 6 L6 17 L10 14.5 L13 20 L15 19 L12 13.5 L17 13.5 Z'/></g><path d='M6 6 L6 17 L10 14.5 L13 20 L15 19 L12 13.5 L17 13.5 Z' fill='%23ffffff' stroke='%23000000' stroke-width='0.8' stroke-linejoin='round'/></svg>") 4 4, default;
}
body.theme-silver {
  cursor: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='28' height='28' viewBox='0 0 28 28'><defs><filter id='g' x='-50%25' y='-50%25' width='200%25' height='200%25'><feGaussianBlur stdDeviation='1.2'/></filter></defs><g filter='url(%23g)' stroke='%23e8eef6' stroke-width='2.2' fill='none' opacity='0.75'><path d='M6 6 L6 17 L10 14.5 L13 20 L15 19 L12 13.5 L17 13.5 Z'/></g><path d='M6 6 L6 17 L10 14.5 L13 20 L15 19 L12 13.5 L17 13.5 Z' fill='%23ffffff' stroke='%23000000' stroke-width='0.8' stroke-linejoin='round'/></svg>") 4 4, default;
}
body.theme-purple {
  cursor: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='28' height='28' viewBox='0 0 28 28'><defs><filter id='g' x='-50%25' y='-50%25' width='200%25' height='200%25'><feGaussianBlur stdDeviation='1.2'/></filter></defs><g filter='url(%23g)' stroke='%23d7b3e6' stroke-width='2.2' fill='none' opacity='0.80'><path d='M6 6 L6 17 L10 14.5 L13 20 L15 19 L12 13.5 L17 13.5 Z'/></g><path d='M6 6 L6 17 L10 14.5 L13 20 L15 19 L12 13.5 L17 13.5 Z' fill='%23ffffff' stroke='%23000000' stroke-width='0.8' stroke-linejoin='round'/></svg>") 4 4, default;
}

/* Crosshair on the board gets a glowing ring — larger SVG with
   feGaussianBlur bloom and a sharper inner stroke. */
.board-section {
  cursor: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='32' height='32' viewBox='0 0 32 32'><defs><filter id='g' x='-50%25' y='-50%25' width='200%25' height='200%25'><feGaussianBlur stdDeviation='1.6'/></filter></defs><g filter='url(%23g)' stroke='%237fd0ff' stroke-width='1.8' fill='none' opacity='0.65'><circle cx='16' cy='16' r='9'/><line x1='16' y1='3' x2='16' y2='8'/><line x1='16' y1='24' x2='16' y2='29'/><line x1='3' y1='16' x2='8' y2='16'/><line x1='24' y1='16' x2='29' y2='16'/></g><g stroke='%23ffffff' stroke-width='1.3' fill='none' opacity='0.95'><circle cx='16' cy='16' r='9'/><line x1='16' y1='3' x2='16' y2='8'/><line x1='16' y1='24' x2='16' y2='29'/><line x1='3' y1='16' x2='8' y2='16'/><line x1='24' y1='16' x2='29' y2='16'/></g></svg>") 16 16, crosshair !important;
}
body.theme-red .board-section {
  cursor: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='32' height='32' viewBox='0 0 32 32'><defs><filter id='g' x='-50%25' y='-50%25' width='200%25' height='200%25'><feGaussianBlur stdDeviation='1.6'/></filter></defs><g filter='url(%23g)' stroke='%23ff8a7a' stroke-width='1.8' fill='none' opacity='0.70'><circle cx='16' cy='16' r='9'/><line x1='16' y1='3' x2='16' y2='8'/><line x1='16' y1='24' x2='16' y2='29'/><line x1='3' y1='16' x2='8' y2='16'/><line x1='24' y1='16' x2='29' y2='16'/></g><g stroke='%23ffffff' stroke-width='1.3' fill='none' opacity='0.95'><circle cx='16' cy='16' r='9'/><line x1='16' y1='3' x2='16' y2='8'/><line x1='16' y1='24' x2='16' y2='29'/><line x1='3' y1='16' x2='8' y2='16'/><line x1='24' y1='16' x2='29' y2='16'/></g></svg>") 16 16, crosshair !important;
