body.theme-green .board-section {
  cursor: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='32' height='32' viewBox='0 0 32 32'><defs><filter id='g' x='-50%25' y='-50%25' width='200%25' height='200%25'><feGaussianBlur stdDeviation='1.6'/></filter></defs><g filter='url(%23g)' stroke='%237ee8a5' stroke-width='1.8' fill='none' opacity='0.70'><circle cx='16' cy='16' r='9'/><line x1='16' y1='3' x2='16' y2='8'/><line x1='16' y1='24' x2='16' y2='29'/><line x1='3' y1='16' x2='8' y2='16'/><line x1='24' y1='16' x2='29' y2='16'/></g><g stroke='%23ffffff' stroke-width='1.3' fill='none' opacity='0.95'><circle cx='16' cy='16' r='9'/><line x1='16' y1='3' x2='16' y2='8'/><line x1='16' y1='24' x2='16' y2='29'/><line x1='3' y1='16' x2='8' y2='16'/><line x1='24' y1='16' x2='29' y2='16'/></g></svg>") 16 16, crosshair !important;
}
body.theme-silver .board-section {
