.sig-flame {
  position: fixed;
  transform: translateX(-50%) scaleY(0);
  transform-origin: bottom center;
  pointer-events: none;
  border-radius: 50% 50% 46% 46% / 62% 62% 38% 38%;
  background: linear-gradient(to top, #ff8a1a 0%, #ff2d1a 30%, #c1121f 60%, rgba(10, 10, 10, 0.5) 100%);
  filter: blur(2px);
  box-shadow: 0 0 26px 6px rgba(255, 60, 20, 0.6);
